import mezz.jei.gui.recipes.layouts.IRecipeLayoutList;
import mezz.jei.gui.recipes.lookups.IFocusedRecipes;
import mezz.jei.gui.recipes.lookups.ILookupState;
import mezz.jei.gui.recipes.lookups.IngredientLookupState;
import mezz.jei.gui.recipes.lookups.SingleCategoryLookupState;
import mezz.jei.gui.recipes.lookups.StaticFocusedRecipes;
import net.minecraft.world.inventory.AbstractContainerMenu;
import org.jspecify.annotations.Nullable;
import org.jetbrains.annotations.Unmodifiable;

import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import java.util.stream.Stream;

public class RecipeGuiLogic implements IRecipeGuiLogic {
	private final IRecipeManager recipeManager;
	private final IIngredientManager ingredientManager;
	private final RecipeTransferService recipeTransferService;
	private final IRecipeLogicStateListener stateListener;

	private boolean initialState = true;
	private ILookupState state;
	private boolean scrolling;
	private RecipeGuiGrid recipeGuiGrid = new RecipeGuiGrid(1, 1);
	private final NavigationHistory<ILookupState> stateHistory = new NavigationHistory<>();
	private final LookupHistory lookupHistory;
	private final IFocusFactory focusFactory;
	private final BookmarkFactory bookmarkFactory;
	private @Nullable IRecipeCategory<?> cachedRecipeCategory;
	private @Nullable IRecipeLayoutList cachedRecipeLayoutsWithButtons;
	private int cachedContainerId = -1;
	private Set<RecipeSorterStage> cachedSorterStages = Set.of();

	public RecipeGuiLogic(
		IRecipeManager recipeManager,
		IIngredientManager ingredientManager,
		LookupHistory lookupHistory,
		RecipeTransferService recipeTransferService,
		IRecipeLogicStateListener stateListener,
		IFocusFactory focusFactory,
		BookmarkFactory bookmarkFactory
	) {
		this.recipeManager = recipeManager;
		this.ingredientManager = ingredientManager;
		this.lookupHistory = lookupHistory;
		this.recipeTransferService = recipeTransferService;
		this.stateListener = stateListener;
		List<IRecipeCategory<?>> recipeCategories = recipeManager.createRecipeCategoryLookup()
			.get()
			.toList();
		this.state = IngredientLookupState.create(
			recipeManager,
			focusFactory.getEmptyFocusGroup(),
			recipeCategories,
			recipeTransferService
		);
		this.focusFactory = focusFactory;
		this.bookmarkFactory = bookmarkFactory;
	}

	@Override
	public void tick() {
		if (cachedRecipeLayoutsWithButtons != null) {
			cachedRecipeLayoutsWithButtons.tick();
		}
	}

	@Override
	public boolean showFocus(IFocusGroup focuses) {
		List<IFocus<?>> allFocuses = focuses.getAllFocuses();
		List<IRecipeCategory<?>> recipeCategories = recipeManager.createRecipeCategoryLookup()
			.limitFocus(allFocuses)
			.get()
			.toList();
		ILookupState state = IngredientLookupState.create(
			recipeManager,
			focuses,
			recipeCategories,
			recipeTransferService
		);

		for (IFocus<?> focus : allFocuses) {
			IngredientBookmark<?> ingredientBookmark = bookmarkFactory.create(focus.getTypedValue());
			this.lookupHistory.add(ingredientBookmark);
		}

		return setState(state, true);
	}

	@Override
	public boolean showRecipes(IFocusedRecipes<?> focusedRecipes, IFocusGroup focuses) {
		focusedRecipes = filterVisibleRecipes(focusedRecipes, focuses);
		if (focusedRecipes.getRecipes().isEmpty()) {
			return false;
		}
		var recipeBookmark = createRecipeBookmark(recipeManager, ingredientManager, recipeTransferService, focusedRecipes, focuses);
		if (recipeBookmark != null) {
			this.lookupHistory.add(recipeBookmark);
		} else {
			for (IFocus<?> focus : focuses.getAllFocuses()) {
				IngredientBookmark<?> ingredientBookmark = bookmarkFactory.create(focus.getTypedValue());
				this.lookupHistory.add(ingredientBookmark);
			}
		}
		ILookupState state = new SingleCategoryLookupState(focusedRecipes, focuses);
		return setState(state, true);
	}

	private <T> IFocusedRecipes<T> filterVisibleRecipes(IFocusedRecipes<T> focusedRecipes, IFocusGroup focuses) {
		if (!(recipeManager instanceof IRecipeVisibility recipeVisibility)) {
			return focusedRecipes;
		}
		IRecipeCategory<T> recipeCategory = focusedRecipes.getRecipeCategory();
		List<T> visibleRecipes = focusedRecipes.getRecipes().stream()
			.filter(recipe -> recipeVisibility.isRecipeVisible(recipeCategory, recipe, focuses))
			.toList();
		return new StaticFocusedRecipes<>(recipeCategory, visibleRecipes);
	}

	private static <T> @Nullable RecipeBookmark<T, ?> createRecipeBookmark(
		IRecipeManager recipeManager,
		IIngredientManager ingredientManager,
		RecipeTransferService recipeTransferService,
		IFocusedRecipes<T> focusedRecipes,
		IFocusGroup focusGroup
	) {
		IRecipeCategory<T> recipeCategory = focusedRecipes.getRecipeCategory();
		List<T> recipes = focusedRecipes.getRecipes();
		if (recipes.size() != 1) {
			return null;
		}
		T recipe = recipes.getFirst();
		return recipeManager.createRecipeLayoutDrawable(recipeCategory, recipe, focusGroup)
			.map(drawable -> RecipeBookmark.create(drawable, ingredientManager, recipeTransferService))
			.orElse(null);
	}

	@Override
	public boolean back() {
		return stateHistory.goBack(state)
			.map(previousState -> setState(previousState, false))
			.orElse(false);
	}

	@Override
	public boolean forward() {
		return stateHistory.goForward(state)
			.map(nextState -> setState(nextState, false))
			.orElse(false);
	}

	@Override
	public void clearHistory() {
		stateHistory.clear();
	}

	private boolean setState(ILookupState state, boolean saveHistory) {
		List<IRecipeCategory<?>> recipeCategories = state.getRecipeCategories();
		if (recipeCategories.isEmpty()) {
			return false;
		}

		if (saveHistory && !initialState) {
			stateHistory.record(this.state);
		}
		this.state = state;
		this.initialState = false;
		this.cachedRecipeCategory = null;
		this.cachedRecipeLayoutsWithButtons = null;
		this.cachedContainerId = -1;
		stateListener.onStateChange();
		return true;
	}

	@Override
	public boolean showAllRecipes() {
		IRecipeCategory<?> recipeCategory = getSelectedRecipeCategory();

		List<IRecipeCategory<?>> recipeCategories = recipeManager.createRecipeCategoryLookup()
			.get()
			.toList();
		final ILookupState state = IngredientLookupState.create(
			recipeManager,
			focusFactory.getEmptyFocusGroup(),
			recipeCategories,
			recipeTransferService
		);
		state.moveToRecipeCategory(recipeCategory);
		setState(state, true);

		return true;
	}

	@Override
	public boolean showCategories(List<IRecipeType<?>> recipeTypes) {
		List<IRecipeCategory<?>> recipeCategories = recipeManager.createRecipeCategoryLookup()
			.limitTypes(recipeTypes)
			.get()
			.toList();

		final ILookupState state = IngredientLookupState.create(
			recipeManager,
			focusFactory.getEmptyFocusGroup(),
			recipeCategories,
			recipeTransferService
		);
		if (state.getRecipeCategories().isEmpty()) {
			return false;
		}

		setState(state, true);

		return true;
	}

	@Override
	public Stream<Consumer<IIngredientAcceptor<?>>> getCraftingStations() {
		IRecipeCategory<?> category = getSelectedRecipeCategory();
		IRecipeType<?> recipeType = category.getRecipeType();
		return recipeManager.createCraftingStationLookup(recipeType)
			.getGroups();
	}

	@Override
	public IRecipeCategory<?> getSelectedRecipeCategory() {
		return state.getFocusedRecipes().getRecipeCategory();
	}

	@Override
	@Unmodifiable
	public List<IRecipeCategory<?>> getRecipeCategories() {
		return state.getRecipeCategories();
	}

	@Override
	public List<IRecipeLayoutWithButtons<?>> getVisibleRecipeLayoutsWithButtons(
		ImmutableSize2i availableSize,
		@Nullable AbstractContainerMenu container,
		BookmarkList bookmarkList,
		RecipesGui recipesGui
	) {
		IRecipeCategory<?> recipeCategory = getSelectedRecipeCategory();

		IClientConfigs jeiClientConfigs = Internal.getClientConfigs();
		IClientConfig clientConfig = jeiClientConfigs.getClientConfig();
		Set<RecipeSorterStage> recipeSorterStages = RecipeSorterStage.getEnabled(clientConfig);

		int containerId = -1;
		if (container != null) {
			containerId = container.containerId;
		}
		if (!recipeSorterStages.equals(cachedSorterStages) ||
			this.cachedRecipeLayoutsWithButtons == null ||
			this.cachedRecipeCategory != recipeCategory ||
			this.cachedContainerId != containerId
		) {
			IFocusedRecipes<?> focusedRecipes = this.state.getFocusedRecipes();

			this.cachedRecipeLayoutsWithButtons = IRecipeLayoutList.create(
				recipeSorterStages,
				container,
				focusedRecipes,
				state.getFocuses(),
				bookmarkList,
				recipeManager,
				recipeTransferService,
				recipesGui
			);
			this.cachedRecipeCategory = recipeCategory;
			this.cachedSorterStages = Set.copyOf(recipeSorterStages);
			this.cachedContainerId = containerId;
		}

		ImmutableSize2i recipeSizeWithButtons = this.cachedRecipeLayoutsWithButtons.findFirst()
			.map(layout -> new ImmutableSize2i(layout.totalWidth(), layout.getRecipeLayout().getRectWithBorder().getHeight()))
			.orElseGet(() -> new ImmutableSize2i(recipeCategory.getWidth(), recipeCategory.getHeight()));

		this.recipeGuiGrid = RecipeGuiGrid.calculate(availableSize, recipeSizeWithButtons, clientConfig.maxRecipeGuiColumns().get());
		this.state.setRecipesPerPage(recipeGuiGrid.recipesPerPage());

		boolean scrolling = isScrolling();
		RecipeGuiScrollState scrollState = getScrollState();
		scrollState.update(recipeGuiGrid.columns(), recipeSizeWithButtons.height(), cachedRecipeLayoutsWithButtons.size(), availableSize.height());
		if (this.scrolling != scrolling) {
			if (scrolling) {
				int pageStart = state.getRecipeIndex() - state.getRecipeIndex() % state.getRecipesPerPage();
				scrollState.scrollToRecipe(pageStart);
			} else {
				state.setRecipeIndex(scrollState.getFirstRecipeIndex());
			}
			this.scrolling = scrolling;
		}
		if (scrolling) {
			return this.cachedRecipeLayoutsWithButtons.subList(scrollState.getFirstRecipeIndex(), scrollState.getEndRecipeIndex());
		}
		return this.state.getVisible(this.cachedRecipeLayoutsWithButtons);
	}

	@Override
	public boolean isScrolling() {
		return Internal.getClientConfigs().getClientConfig().recipeGuiNavigationMode().get() == RecipeGuiNavigationMode.SCROLLING;
	}

	@Override
	public RecipeGuiScrollState getScrollState() {
		return state.getScrollState();
	}

	@Override
	public boolean scrollRecipes(double pixels) {
		if (getScrollState().scroll(pixels)) {
			stateListener.onStateChange();
			return true;
		}
		return false;
	}

	@Override
	public int getVisibleScrollAmount() {
		return getScrollState().getVisibleHeight();
	}

	@Override
	public int getHiddenScrollAmount() {
		return getScrollState().getMaxScroll();
	}

	@Override
	public float getScrollOffsetY() {
		return getScrollState().getScrollOffset();
	}

	@Override
	public void setScrollOffsetY(float scrollOffsetY) {
		if (getScrollState().setScrollOffset(scrollOffsetY)) {
			stateListener.onStateChange();
		}
	}

	@Override
	public RecipeGuiGrid getRecipeGuiGrid() {
		return recipeGuiGrid;
	}

	@Override
	public boolean nextRecipeCategory() {
		if (state.nextRecipeCategory()) {
			stateListener.onStateChange();
			return true;
		}
		return false;
	}

	@Override
	public void setRecipeCategory(IRecipeCategory<?> category) {
		if (state.moveToRecipeCategory(category)) {
			stateListener.onStateChange();
		}
	}

	@Override
	public boolean hasMultiplePages() {
		List<?> recipes = state.getFocusedRecipes().getRecipes();
		return recipes.size() > state.getRecipesPerPage();
	}

	@Override
	public boolean previousRecipeCategory() {
		if (state.previousRecipeCategory()) {
			stateListener.onStateChange();
			return true;
		}
		return false;
	}

	@Override
	public void goToFirstPage() {
		state.goToFirstPage();
		stateListener.onStateChange();
	}

	@Override
	public boolean nextPage() {
		if (isScrolling()) {
			return scrollRecipes(getScrollState().getVisibleHeight());
		}
		if (state.nextPage()) {
			stateListener.onStateChange();
			return true;
		}
		return false;
	}

	@Override
	public boolean previousPage() {
		if (isScrolling()) {
			return scrollRecipes(-getScrollState().getVisibleHeight());
		}
		if (state.previousPage()) {
			stateListener.onStateChange();
			return true;
		}
		return false;
	}

	@Override
	public String getPageString() {
		int pageIndex = MathUtil.divideCeil(state.getRecipeIndex() + 1, state.getRecipesPerPage());
		return pageIndex + "/" + state.pageCount();
	}

	@Override
	public boolean hasMultipleCategories() {
		return state.getRecipeCategories().size() > 1;
	}

	@Override
	public boolean hasAllCategories() {
		long categoryCount = recipeManager.createRecipeCategoryLookup()
			.get()
			.count();

		return state.getRecipeCategories().size() == categoryCount;
	}

}

package mezz.jei.gui.input;

import com.mojang.blaze3d.platform.InputConstants;
import mezz.jei.common.input.IInternalKeyMappings;
import mezz.jei.common.input.UserInput;
import mezz.jei.gui.util.GuiEventListenerUtil;
import net.minecraft.client.gui.screens.ChatScreen;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.input.CharacterEvent;
import net.minecraft.client.input.MouseButtonEvent;

/** Connects Minecraft's input callbacks to JEI's input controller. */
public class ClientInputHandler {
	private final GuiInputController controller;
	private final IInternalKeyMappings keybindings;

	public ClientInputHandler(GuiInputController controller, IInternalKeyMappings keybindings) {
		this.controller = controller;
		this.keybindings = keybindings;
	}

	public void onGuiChanged() {
		controller.screenChanged();
	}

	/**
	 * Offers key presses to JEI before the Minecraft screen handles them, when no Minecraft
	 * text field has keyboard focus. The Focus Search shortcut and chat also get this early check.
	 *
	 * <p>For example, when a player uses Focus Search in the creative inventory, JEI can
	 * select its search field before the creative inventory's search field handles the key.</p>
	 */
	public boolean onKeyboardKeyPressedPre(Screen screen, UserInput input) {
		// Focus Search transfers keyboard focus even when the creative inventory's search field is selected.
		if (screen instanceof ChatScreen || input.is(keybindings.getFocusSearch()) || !isContainerTextFieldFocused(screen)) {
			return controller.keyPressed(screen, input);
		}
		return false;
	}

	/**
	 * Offers a key press to JEI after the Minecraft screen has declined it, when a Minecraft
	 * text field has keyboard focus. This lets that text field handle the key first.
	 */
	public boolean onKeyboardKeyPressedPost(Screen screen, UserInput input) {
		if (!(screen instanceof ChatScreen) && isContainerTextFieldFocused(screen)) {
			return controller.keyPressed(screen, input);
		}
		return false;
	}

	/**
	 * Offers typed characters to JEI before the Minecraft screen handles them, when no
	 * Minecraft text field has keyboard focus. JEI inserts them only if its search field
	 * has keyboard focus.
	 */
	public boolean onKeyboardCharTypedPre(Screen screen, CharacterEvent event) {
		if (!isContainerTextFieldFocused(screen)) {
			return controller.charTyped(event);
		}
		return false;
	}

	/**
	 * Offers typed characters to JEI after a Minecraft text field has had the first chance
	 * to handle them. JEI inserts them only if its search field has keyboard focus.
	 */
	public void onKeyboardCharTypedPost(Screen screen, CharacterEvent event) {
		if (isContainerTextFieldFocused(screen)) {
			controller.charTyped(event);
		}
	}

	public boolean onGuiMouseClicked(Screen screen, UserInput input) {
		return controller.mousePressed(screen, input);
	}

	public boolean onGuiMouseReleased(Screen screen, UserInput input) {
		return controller.mouseReleased(screen, input);
	}

	public boolean onGuiMouseScroll(double mouseX, double mouseY, double scrollDeltaX, double scrollDeltaY) {
		return controller.mouseScrolled(mouseX, mouseY, scrollDeltaX, scrollDeltaY);
	}

	public boolean onGuiMouseDragged(Screen screen, MouseButtonEvent event, double dragX, double dragY) {
		InputConstants.Key input = InputConstants.Type.MOUSE.getOrCreate(event.button());
		return controller.mouseDragged(screen, event.x(), event.y(), input, dragX, dragY);
	}

	private boolean isContainerTextFieldFocused(Screen screen) {
		return GuiEventListenerUtil.getEditBoxes(screen)
			.anyMatch(textField -> textField.isActive() && textField.isFocused());
	}
}

package mezz.jei.gui.startup;

import mezz.jei.api.recipe.IFocusFactory;
import mezz.jei.api.runtime.IBookmarkManager;
import mezz.jei.api.runtime.IEditModeConfig;
import mezz.jei.api.runtime.IIngredientManager;
import mezz.jei.api.runtime.IScreenHelper;
import mezz.jei.common.config.IClientConfig;
import mezz.jei.common.config.IClientToggleState;
import mezz.jei.common.input.IInternalKeyMappings;
import mezz.jei.common.network.IConnectionToServer;
import mezz.jei.gui.bookmarks.BookmarkList;
import mezz.jei.gui.input.ClientInputHandler;
import mezz.jei.gui.input.GuiContainerWrapper;
import mezz.jei.gui.input.GuiInputController;
import mezz.jei.gui.input.GuiInputScene;
import mezz.jei.gui.input.IngredientFocusSource;
import mezz.jei.gui.input.InputArea;
import mezz.jei.gui.input.InputCommands;
import mezz.jei.gui.input.handlers.BookmarkCommands;
import mezz.jei.gui.input.handlers.ChatCommands;
import mezz.jei.gui.input.handlers.IngredientCommands;
import mezz.jei.gui.overlay.IngredientListOverlay;
import mezz.jei.gui.overlay.bookmarks.BookmarkOverlay;
import mezz.jei.gui.recipes.RecipesGui;
import mezz.jei.gui.util.CheatModeUtil;
import mezz.jei.gui.util.FocusUtil;

/**
 * Input areas and Minecraft event handling for JEI's screens.
 *
 * @param scene the input areas, ordered from front to back
 * @param handler sends Minecraft input events to JEI's input controller
 */
public record JeiInputSetup(GuiInputScene scene, ClientInputHandler handler) {
	public static JeiInputSetup create(
		IngredientListOverlay ingredientListOverlay,
		BookmarkOverlay bookmarkOverlay,
		RecipesGui recipesGui,
		BookmarkList bookmarkList,
		IBookmarkManager bookmarkManager,
		IScreenHelper screenHelper,
		IIngredientManager ingredientManager,
		IFocusFactory focusFactory,
		FocusUtil focusUtil,
		IClientConfig clientConfig,
		IClientToggleState toggleState,
		IEditModeConfig editModeConfig,
		IConnectionToServer serverConnection,
		IInternalKeyMappings keyMappings
	) {
		var searchInputLayer = ingredientListOverlay.getSearchInputLayer();
		InputArea searchInputArea = searchInputLayer.createInputArea(keyMappings);
		InputArea recipeTooltipInputArea = recipesGui.createTooltipInputArea();
		InputArea bookmarkTooltipInputArea = bookmarkOverlay.createTooltipInputArea();
		InputArea recipeInputArea = recipesGui.createInputArea(keyMappings);
		InputArea ingredientInputArea = ingredientListOverlay.createInputArea(keyMappings);
		InputArea bookmarkInputArea = bookmarkOverlay.createInputArea(keyMappings);
		GuiContainerWrapper containerWrapper = new GuiContainerWrapper(screenHelper);
		InputArea containerInputArea = containerWrapper.createInputArea(recipesGui, focusFactory);
		ChatCommands chatCommands = new ChatCommands(recipesGui, focusUtil, screenHelper, bookmarkManager);
		InputArea chatInputArea = chatCommands.createInputArea(keyMappings);
		GuiInputScene inputScene = new GuiInputScene(
			searchInputArea,
			recipeTooltipInputArea,
			bookmarkTooltipInputArea,
			recipeInputArea,
			ingredientInputArea,
			bookmarkInputArea,
			containerInputArea,
			chatInputArea
		);

		InputCommands commands = new InputCommands(screen -> screenHelper.getGuiProperties(screen).isPresent());
		IngredientFocusSource focusSource = new IngredientFocusSource(inputScene);
		IngredientCommands ingredientCommands = new IngredientCommands(
			focusSource,
			keyMappings,
			recipesGui,
			focusUtil,
			ingredientManager,
			toggleState,
			editModeConfig,
			clientConfig,
			serverConnection
		);
		ingredientCommands.registerInputCommands(commands);
		BookmarkCommands bookmarkCommands = new BookmarkCommands(
			focusSource,
			bookmarkList,
			bookmarkOverlay,
			inputScene,
			clientConfig,
			recipesGui
		);
		bookmarkCommands.registerInputCommands(commands, keyMappings);
		commands.add(
			"Toggle Overlay",
			keyMappings.getToggleOverlay(),
			() -> true,
			toggleState::toggleOverlayEnabled
		);
		commands.add(
			"Toggle Bookmark Overlay",
			keyMappings.getToggleBookmarkOverlay(),
			() -> true,
			toggleState::toggleBookmarkEnabled
		);
		commands.add(
			"Toggle Cheat Mode",
			keyMappings.getToggleCheatMode(),
			() -> true,
			() -> CheatModeUtil.toggleCheatMode(toggleState)
		);
		commands.add(
			"Toggle Edit Mode",
			keyMappings.getToggleEditMode(),
			() -> true,
			toggleState::toggleEditModeEnabled
		);

		GuiInputController controller = new GuiInputController(inputScene, commands, searchInputLayer, keyMappings);
		ClientInputHandler handler = new ClientInputHandler(controller, keyMappings);
		return new JeiInputSetup(inputScene, handler);
	}
}

package mezz.jei.gui.input;

import com.mojang.blaze3d.platform.InputConstants;
import mezz.jei.common.config.DebugConfig;
import mezz.jei.common.input.IInternalKeyMappings;
import mezz.jei.common.input.UserInput;
import mezz.jei.common.input.interaction.ConsumedInput;
import mezz.jei.common.input.interaction.IInputInteraction;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.input.CharacterEvent;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.jspecify.annotations.Nullable;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Sends input to JEI controls and shortcuts, keeping mouse interactions until release or cancellation.
 * Focused text editing gets the first chance to handle keyboard input. Controls under
 * the pointer are tried before shortcuts. Shortcut priority is the selected input area's
 * shortcuts, then shared shortcuts, then other areas' shortcuts that work anywhere on the screen.
 *
 * <p>For example, a player editing "stone" presses Backspace. The search field removes
 * the "e", even if Backspace is also bound to show or hide JEI.</p>
 */
public final class GuiInputController {
	private static final Logger LOGGER = LogManager.getLogger();
	/** Input areas from front to back, shared with ingredient lookup. */
	private final GuiInputScene scene;
	/** Shortcuts shared by input areas, such as looking up recipes and showing or hiding overlays. */
	private final InputCommands commands;
	private final ITextInputHandler editor;
	private final IInternalKeyMappings keys;
	/** Interactions and original screens for mouse buttons that are still held. */
	private final Map<InputConstants.Key, MouseCapture> captures = new HashMap<>();
	/** Detects screen changes even when a handler returns to the same screen before finishing. */
	private int screenChangeCount;

	public GuiInputController(GuiInputScene scene, InputCommands commands, ITextInputHandler editor, IInternalKeyMappings keys) {
		this.scene = scene;
		this.commands = commands;
		this.editor = editor;
		this.keys = keys;
	}

	public boolean keyPressed(Screen screen, UserInput input) {
		return scene.dispatch(input.getMouseX(), input.getMouseY(), () -> {
			int initialScreenChangeCount = screenChangeCount;
			Optional<IInputInteraction> action = resolve(screen, input);
			if (!isScreenUnchanged(screen, initialScreenChangeCount)) {
				action.ifPresent(IInputInteraction::cancel);
				return true;
			}
			action.ifPresent(interaction -> interaction.complete(input));
			return action.isPresent();
		});
	}

	public boolean mousePressed(Screen screen, UserInput input) {
		MouseCapture previous = captures.get(input.getKey());
		if (previous != null && previous.keepsCaptureOnRepeatedPress()) {
			return true;
		}
		cancel(input.getKey());
		return scene.dispatch(input.getMouseX(), input.getMouseY(), () -> {
			InputArea target = scene.getTarget(input.getMouseX(), input.getMouseY()).orElse(null);
			int initialScreenChangeCount = screenChangeCount;
			IInputInteraction interaction = resolve(screen, input).orElse(null);
			IInputInteraction ingredientDrag = null;
			if (isScreenUnchanged(screen, initialScreenChangeCount) && input.is(keys.getLeftClick())) {
				ingredientDrag = scene.startDrag(screen, input).orElse(null);
			}
			if (interaction == null && ingredientDrag == null && target != null && target.blocksUnhandledMouseInput()) {
				interaction = ConsumedInput.INSTANCE;
			}
			if (interaction == null && ingredientDrag == null) {
				return false;
			}
			MouseCapture capture = new MouseCapture(screen, interaction, ingredientDrag);
			if (isScreenUnchanged(screen, initialScreenChangeCount)) {
				captures.put(input.getKey(), capture);
			} else {
				capture.cancel();
			}
			return true;
		});
	}

	private Optional<IInputInteraction> resolve(Screen screen, UserInput input) {
		InputArea target = scene.getTarget(input.getMouseX(), input.getMouseY()).orElse(null);
		if (DebugConfig.isDebugInputsEnabled()) {
			String targetName = "none";
			if (target != null) {
				targetName = target.name();
			}
			LOGGER.debug("JEI input {} targeting {}", input, targetName);
		}
		boolean editing = input.isKeyboardInput() && editor.hasKeyboardFocus();
		if (editing) {
			Optional<IInputInteraction> edit = editor.beginInput(screen, input, keys);
			if (edit.isPresent()) {
				return edit;
			}
		}
		if (target != null) {
			if (!editing || target.area() != editor) {
				Optional<IInputInteraction> control = target.controls().beginInput(screen, input, keys);
				if (control.isPresent()) {
					return control;
				}
			}
			Optional<IInputInteraction> shortcut = target.commands().resolve(screen, input, true);
			if (shortcut.isPresent()) {
				return shortcut;
			}
		}
		Optional<IInputInteraction> global = commands.resolve(screen, input, false);
		if (global.isPresent()) {
			return global;
		}
		for (InputArea inputArea : scene.getInputAreas()) {
			if (inputArea != target) {
				Optional<IInputInteraction> shortcut = inputArea.commands().resolve(screen, input, false);
				if (shortcut.isPresent()) {
					return shortcut;
				}
			}
		}
		return Optional.empty();
	}

	public boolean mouseReleased(Screen screen, UserInput input) {
		MouseCapture capture = captures.remove(input.getKey());
		if (capture != null && capture.screen() != screen) {
			capture.cancel();
			return true;
		}
		InputArea target = scene.getTarget(input.getMouseX(), input.getMouseY()).orElse(null);
		if (target == null || target.area() != editor) {
			editor.clearFocus();
		}
		if (capture == null) {
			return false;
		}
		int initialScreenChangeCount = screenChangeCount;
		if (capture.interaction() != null) {
			capture.interaction().complete(input);
		}
		if (capture.ingredientDrag() != null) {
			if (isScreenUnchanged(screen, initialScreenChangeCount)) {
				capture.ingredientDrag().complete(input);
			} else {
				capture.ingredientDrag().cancel();
			}
		}
		return true;
	}

	public boolean mouseDragged(Screen screen, double mouseX, double mouseY, InputConstants.Key button, double dragX, double dragY) {
		MouseCapture capture = captures.get(button);
		if (capture == null) {
			return scene.dragApiHandlers(mouseX, mouseY, button, dragX, dragY);
		}
		if (capture.screen() != screen) {
			cancel(button);
			return true;
		}
		int initialScreenChangeCount = screenChangeCount;
		if (capture.interaction() != null) {
			capture.interaction().drag(mouseX, mouseY, button, dragX, dragY);
		}
		if (capture.ingredientDrag() != null && isScreenUnchanged(screen, initialScreenChangeCount)) {
			capture.ingredientDrag().drag(mouseX, mouseY, button, dragX, dragY);
		}
		if (isScreenUnchanged(screen, initialScreenChangeCount) && !capture.capturesMouseMovement()) {
			scene.dragApiHandlers(mouseX, mouseY, button, dragX, dragY);
		}
		return true;
	}

	public boolean mouseScrolled(double mouseX, double mouseY, double scrollX, double scrollY) {
		return scene.dispatch(mouseX, mouseY, () -> {
			InputArea target = scene.getTarget(mouseX, mouseY).orElse(null);
			if (target == null) {
				return false;
			}
			return target.controls().scroll(mouseX, mouseY, scrollX, scrollY) || target.blocksUnhandledMouseInput();
		});
	}

	public boolean charTyped(CharacterEvent event) {
		return editor.hasKeyboardFocus() && editor.onCharTyped(event);
	}

	public void screenChanged() {
		screenChangeCount++;
		List<MouseCapture> pending = List.copyOf(captures.values());
		captures.clear();
		pending.forEach(MouseCapture::cancel);
		editor.clearFocus();
		scene.resetInput();
	}

	private boolean isScreenUnchanged(Screen screen, int initialScreenChangeCount) {
		return screenChangeCount == initialScreenChangeCount && Minecraft.getInstance().gui.screen() == screen;
	}

	private void cancel(InputConstants.Key button) {
		MouseCapture capture = captures.remove(button);
		if (capture != null) {
			capture.cancel();
		}
	}

	/**
	 * Pending interactions for one mouse button. A press can select both a click action
	 * and an ingredient drag.
	 *
	 * @param screen screen where the press was accepted; a release on another screen cancels it
	 * @param interaction interaction for the selected control or shortcut, or null if only a drag started
	 * @param ingredientDrag interaction for an ingredient drag started by the same press, or null if none started
	 */
	private record MouseCapture(Screen screen, @Nullable IInputInteraction interaction, @Nullable IInputInteraction ingredientDrag) {
		private void cancel() {
			if (interaction != null) {
				interaction.cancel();
			}
			if (ingredientDrag != null) {
				ingredientDrag.cancel();
			}
		}

		private boolean capturesMouseMovement() {
			return (interaction != null && interaction.capturesMouseMovement()) ||
				(ingredientDrag != null && ingredientDrag.capturesMouseMovement());
		}

		private boolean keepsCaptureOnRepeatedPress() {
			return (interaction != null && interaction.keepsCaptureOnRepeatedPress()) || (ingredientDrag != null && ingredientDrag.keepsCaptureOnRepeatedPress());
		}
	}
}

package mezz.jei.neoforge.startup;

import mezz.jei.common.input.UserInput;
import mezz.jei.gui.events.GuiEventHandler;
import mezz.jei.gui.input.ClientInputHandler;
import mezz.jei.gui.input.GuiTextFieldFilter;
import mezz.jei.gui.input.PinnedTooltipManager;
import mezz.jei.gui.startup.JeiEventHandlers;
import mezz.jei.neoforge.events.RuntimeEventSubscriptions;
import mezz.jei.neoforge.input.ForgeUserInput;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;
import net.minecraft.client.input.CharacterEvent;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.neoforged.neoforge.client.event.RenderTooltipEvent;
import net.neoforged.neoforge.client.event.ScreenEvent;
import org.joml.Matrix3x2fStack;

public class EventRegistration {
	public static void registerEvents(RuntimeEventSubscriptions subscriptions, JeiEventHandlers eventHandlers) {
		ClientInputHandler clientInputHandler = eventHandlers.clientInputHandler();
		subscriptions.onClear(clientInputHandler::onGuiChanged);
		registerClientInputHandler(subscriptions, clientInputHandler);

		GuiEventHandler guiEventHandler = eventHandlers.guiEventHandler();
		registerGuiHandler(subscriptions, guiEventHandler);
	}

	private static void registerClientInputHandler(RuntimeEventSubscriptions subscriptions, ClientInputHandler handler) {
		subscriptions.register(ScreenEvent.Init.Post.class, event -> handler.onGuiChanged());
		subscriptions.register(ScreenEvent.Closing.class, event -> handler.onGuiChanged());

		subscriptions.register(ScreenEvent.KeyPressed.Pre.class, event -> {
			Screen screen = event.getScreen();
			UserInput input = ForgeUserInput.fromEvent(event);
			if (handler.onKeyboardKeyPressedPre(screen, input)) {
				event.setCanceled(true);
			}
		});
		subscriptions.register(ScreenEvent.KeyPressed.Post.class, event -> {
			Screen screen = event.getScreen();
			UserInput input = ForgeUserInput.fromEvent(event);
			if (handler.onKeyboardKeyPressedPost(screen, input)) {
				event.setCanceled(true);
			}
		});

		subscriptions.register(ScreenEvent.CharacterTyped.Pre.class, event -> {
			Screen screen = event.getScreen();
			CharacterEvent characterEvent = event.getCharacterEvent();
			if (handler.onKeyboardCharTypedPre(screen, characterEvent)) {
				event.setCanceled(true);
			}
		});
		subscriptions.register(ScreenEvent.CharacterTyped.Post.class, event -> {
			Screen screen = event.getScreen();
			CharacterEvent characterEvent = event.getCharacterEvent();
			handler.onKeyboardCharTypedPost(screen, characterEvent);
		});

		subscriptions.register(ScreenEvent.Preedit.Pre.class, event -> {
			Screen screen = event.getScreen();
			if (screen.getFocused() instanceof GuiTextFieldFilter searchField && searchField.isFocused()) {
				searchField.preeditUpdated(event.getPreeditEvent());
				event.setCanceled(true);
			}
		});

		subscriptions.register(ScreenEvent.MouseButtonPressed.Pre.class, event -> {
			ForgeUserInput.fromEvent(event)
				.ifPresent(input -> {
					Screen screen = event.getScreen();
					if (handler.onGuiMouseClicked(screen, input)) {
						event.setCanceled(true);
					}
				});
		});
		subscriptions.register(ScreenEvent.MouseButtonReleased.Pre.class, event -> {
			ForgeUserInput.fromEvent(event)
				.ifPresent(input -> {
					Screen screen = event.getScreen();
					if (handler.onGuiMouseReleased(screen, input)) {
						event.setCanceled(true);
					}
				});
		});

		subscriptions.register(ScreenEvent.MouseScrolled.Pre.class, event -> {
			double mouseX = event.getMouseX();
			double mouseY = event.getMouseY();
			double scrollDeltaX = event.getScrollDeltaX();
			double scrollDeltaY = event.getScrollDeltaY();
			if (handler.onGuiMouseScroll(mouseX, mouseY, scrollDeltaX, scrollDeltaY)) {
				event.setCanceled(true);
			}
		});

		subscriptions.register(ScreenEvent.MouseDragged.Pre.class, event -> {
			Screen screen = event.getScreen();
			if (handler.onGuiMouseDragged(screen, event.getMouseButtonEvent(), event.getDragX(), event.getDragY())) {
				event.setCanceled(true);
			}
		});
	}

	public static void registerGuiHandler(
		RuntimeEventSubscriptions subscriptions,
		GuiEventHandler guiEventHandler
	) {
		subscriptions.register(EventPriority.HIGHEST, ScreenEvent.Render.Pre.class, event -> {
			Screen screen = event.getScreen();
			guiEventHandler.updateForScreenRender(screen, event.getMouseX(), event.getMouseY());
		});
		subscriptions.register(EventPriority.HIGHEST, RenderTooltipEvent.GatherComponents.class, event -> {
			if (PinnedTooltipManager.shouldSuppressExternalTooltip()) {
				event.setCanceled(true);
			}
		});
		subscriptions.register(ClientTickEvent.Post.class, event -> {
			if (Minecraft.getInstance().gui.screen() != null) {
				guiEventHandler.onClientTick();
			}
		});
		subscriptions.register(ScreenEvent.Init.Post.class, event -> {
			Screen screen = event.getScreen();
			guiEventHandler.onGuiInit(screen);
		});
		subscriptions.register(ScreenEvent.Opening.class, event -> {
			Screen screen = event.getScreen();
			guiEventHandler.onGuiOpen(screen);
		});
		subscriptions.register(EventPriority.LOWEST, ScreenEvent.Render.Foreground.class, event -> {
			Screen screen = event.getScreen();
			var guiGraphics = event.getGuiGraphics();
			int mouseX = event.getMouseX();
			int mouseY = event.getMouseY();
			guiGraphics.nextStratum();
			runWithIdentityPose(guiGraphics, () -> {
				guiEventHandler.drawForScreenForeground(screen, guiGraphics, mouseX, mouseY);
			});
		});
		subscriptions.register(EventPriority.HIGHEST, ScreenEvent.Render.Background.class, event -> {
			Screen screen = event.getScreen();
			var guiGraphics = event.getGuiGraphics();
			runWithIdentityPose(guiGraphics, () -> {
				guiEventHandler.drawForScreenBackground(screen, guiGraphics);
			});
		});
		subscriptions.register(ScreenEvent.RenderInventoryMobEffects.class, event -> {
			if (event.getScreen() instanceof AbstractContainerScreen<?> screen &&
				guiEventHandler.renderCompactPotionIndicators(screen)
			) {
				event.setCompact(true);
			}
		});
	}

	private static void runWithIdentityPose(GuiGraphicsExtractor guiGraphics, Runnable runnable) {
		Matrix3x2fStack pose = guiGraphics.pose();
		pose.pushMatrix();
		pose.identity();
		try {
			runnable.run();
		} finally {
			pose.popMatrix();
		}
	}
}

package mezz.jei.common.input.handlers;

import mezz.jei.common.input.IInputTarget;
import mezz.jei.common.input.IInternalKeyMappings;
import mezz.jei.common.input.UserInput;
import mezz.jei.common.input.interaction.IInputInteraction;
import net.minecraft.client.gui.screens.Screen;

import java.util.List;
import java.util.Optional;
import java.util.function.BooleanSupplier;

/** Tries a group of controls in order and stops at the first one that handles the input. */
public class InputGroup implements IInputTarget {
	/** Identifies the group in debug output. */
	private final String name;
	/** Controls in priority order; the first visible child accepting an event handles it. */
	private final List<Child> children;

	/**
	 * A control that can be shown or hidden without rebuilding the group.
	 *
	 * @param visible whether to send the control a press or scroll event; checked for each event
	 * @param target the control receiving those events; reset with the group even when hidden
	 */
	public record Child(BooleanSupplier visible, IInputTarget target) {
	}

	public InputGroup(String name) {
		this(name, List.of());
	}

	public InputGroup(String name, Child... children) {
		this.name = name;
		this.children = List.of(children);
	}

	public InputGroup(String name, IInputTarget... children) {
		this(name, List.of(children));
	}

	public InputGroup(String name, List<IInputTarget> children) {
		this.name = name;
		this.children = children.stream().map(child -> new Child(() -> true, child)).toList();
	}

	@Override
	public Optional<IInputInteraction> beginInput(Screen screen, UserInput input, IInternalKeyMappings keys) {
		for (Child child : children) {
			if (!child.visible().getAsBoolean()) {
				continue;
			}
			Optional<IInputInteraction> interaction = child.target().beginInput(screen, input, keys);
			if (interaction.isPresent()) {
				return interaction;
			}
		}
		return Optional.empty();
	}

	@Override
	public boolean scroll(double mouseX, double mouseY, double scrollX, double scrollY) {
		for (Child child : children) {
			if (child.visible().getAsBoolean() && child.target().scroll(mouseX, mouseY, scrollX, scrollY)) {
				return true;
			}
		}
		return false;
	}

	@Override
	public void resetInput() {
		children.forEach(child -> child.target().resetInput());
	}

	@Override
	public String toString() {
		return name + children;
	}
}

package mezz.jei.gui.recipes;

import mezz.jei.common.config.IClientConfig;

final class RecipeGuiSizing {
	private RecipeGuiSizing() {

	}

	static Size calculateInitialSize(int screenHeight, boolean centerSearchBarEnabled, int maxHeight) {
		int ySize;
		if (centerSearchBarEnabled) {
			ySize = screenHeight - 76;
		} else {
			ySize = screenHeight - 58;
		}
		if (ySize < IClientConfig.minRecipeGuiHeight) {
			ySize = IClientConfig.minRecipeGuiHeight;
		}

		int extraSpace = 0;
		if (ySize > maxHeight) {
			extraSpace = ySize - maxHeight;
			ySize = maxHeight;
		}
		return new Size(ySize, extraSpace);
	}

	record Size(int ySize, int extraSpace) {}
}

package mezz.jei.gui.input;

import mezz.jei.common.input.IInputTarget;
import mezz.jei.common.input.IMouseOverable;
import mezz.jei.common.input.handlers.InputGroup;
import mezz.jei.common.input.interaction.ApiInputAdapter.IMouseDragHandler;
import org.jspecify.annotations.Nullable;

import java.util.List;

/**
 * A screen area with its controls, shortcuts, and ingredient drag sources.
 * Examples include the ingredient list, recipe display, and tooltips. Create one with {@link #builder}.
 *
 * @param name label used in debug logs
 * @param area tests whether this input area is visible and contains the mouse pointer;
 *             also supplies ingredient lookup when it implements {@link IRecipeFocusSource}
 * @param blocksUnhandledMouseInput whether to block mouse input from reaching the Minecraft screen
 *                                  even when no control or shortcut handles it
 * @param controls input handler for the controls, tried before this input area's shortcuts
 * @param commands shortcuts for this input area; those with {@link InputCommands.Scope#SCREEN}
 *                 can also run when the pointer is elsewhere
 * @param dragSources sources that can start an ingredient drag, tried in order on left mouse button press;
 *                    the first to accept it starts the drag, along with any selected click action
 * @param apiDragHandler public recipe callbacks to try under the pointer when no control is using mouse movement;
 *                       null for input areas without recipe callbacks
 */
public record InputArea(String name, IMouseOverable area, boolean blocksUnhandledMouseInput, IInputTarget controls,
	InputCommands commands, List<DragSource> dragSources, @Nullable IMouseDragHandler apiDragHandler) {
	public InputArea {
		dragSources = List.copyOf(dragSources);
	}

	/**
	 * Starts an input area with no controls, shortcuts, or drag sources.
	 * By default, mouse input that JEI does not handle can reach the Minecraft screen.
	 *
	 * @param name label used in debug logs
	 * @param area tests visibility and whether the mouse pointer is inside; may also supply ingredient lookup
	 */
	public static Builder builder(String name, IMouseOverable area) {
		return new Builder(name, area);
	}

	/** Configures the controls, shortcuts, and dragging available in an input area. */
	public static final class Builder {
		private final String name;
		private final IMouseOverable area;
		private boolean blocksUnhandledMouseInput;
		private IInputTarget controls;
		private InputCommands commands = new InputCommands();
		private List<DragSource> dragSources = List.of();
		private @Nullable IMouseDragHandler apiDragHandler;

		private Builder(String name, IMouseOverable area) {
			this.name = name;
			this.area = area;
			this.controls = new InputGroup(name);
		}

		/**
		 * Stops unhandled mouse input from reaching the Minecraft screen behind this area.
		 * For example, clicking empty space in the ingredient list does not activate an inventory
		 * slot behind it. Controls and shortcuts can still handle input within this area.
		 */
		public Builder blockUnhandledMouseInput() {
			this.blocksUnhandledMouseInput = true;
			return this;
		}

		/** Sets the controls to try before this area's shortcuts. */
		public Builder controls(IInputTarget controls) {
			this.controls = controls;
			return this;
		}

		/** Sets this area's shortcuts. If omitted, the area starts with an empty collection. */
		public Builder commands(InputCommands commands) {
			this.commands = commands;
			return this;
		}

		/** Sets the ingredient drag sources to try, in order, when the player presses the left mouse button. */
		public Builder dragSources(List<DragSource> dragSources) {
			this.dragSources = dragSources;
			return this;
		}

		/** Sets public recipe drag callbacks to try when no internal control is using mouse movement. */
		public Builder apiDragHandler(IMouseDragHandler apiDragHandler) {
			this.apiDragHandler = apiDragHandler;
			return this;
		}

		public InputArea build() {
			return new InputArea(name, area, blocksUnhandledMouseInput, controls, commands, dragSources, apiDragHandler);
		}
	}
}

package mezz.jei.gui.recipes;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Optional;

final class NavigationHistory<T> {
	private final Deque<T> backwardHistory = new ArrayDeque<>();
	private final Deque<T> forwardHistory = new ArrayDeque<>();

	public void record(T value) {
		backwardHistory.push(value);
		forwardHistory.clear();
	}

	public Optional<T> goBack(T currentValue) {
		T previousValue = backwardHistory.poll();
		if (previousValue == null) {
			return Optional.empty();
		}
		forwardHistory.push(currentValue);
		return Optional.of(previousValue);
	}

	public Optional<T> goForward(T currentValue) {
		T nextValue = forwardHistory.poll();
		if (nextValue == null) {
			return Optional.empty();
		}
		backwardHistory.push(currentValue);
		return Optional.of(nextValue);
	}

	public void clear() {
		backwardHistory.clear();
		forwardHistory.clear();
	}
}

package mezz.jei.gui.input;

import com.mojang.blaze3d.platform.InputConstants;
import mezz.jei.common.input.IGuiInputLayer;
import mezz.jei.common.input.IMouseOverable;
import mezz.jei.common.input.UserInput;
import mezz.jei.common.input.interaction.IInputInteraction;
import net.minecraft.client.gui.screens.Screen;
import org.jspecify.annotations.Nullable;

import java.util.List;
import java.util.Optional;
import java.util.function.Supplier;
import java.util.stream.Stream;

/**
 * Lists input areas ({@link InputArea}) from front to back and selects the first under the mouse pointer.
 * Input handling and ingredient lookup share that selection for the duration of one event.
 *
 * <p>For example, a player hovers over cobblestone in a recipe tooltip that covers an
 * iron ingot in the ingredient list. Pressing the Show Recipes key looks up cobblestone,
 * because the tooltip is in front of the list.</p>
 */
public final class GuiInputScene {
	/** Input areas from front to back; also the order for trying shortcuts outside the selected input area. */
	private final List<InputArea> inputAreas;
	/** Input area chosen for the event being handled; null when no event is being handled. */
	private @Nullable HitTest dispatchTarget;

	public GuiInputScene(InputArea... inputAreas) {
		this.inputAreas = List.of(inputAreas);
	}

	public List<InputArea> getInputAreas() {
		return inputAreas;
	}

	public <T> T dispatch(double mouseX, double mouseY, Supplier<T> action) {
		HitTest previousTarget = this.dispatchTarget;
		this.dispatchTarget = new HitTest(findTarget(mouseX, mouseY).orElse(null));
		try {
			return action.get();
		} finally {
			this.dispatchTarget = previousTarget;
		}
	}

	public Optional<InputArea> getTarget(double mouseX, double mouseY) {
		if (dispatchTarget != null) {
			return Optional.ofNullable(dispatchTarget.inputArea());
		}
		return findTarget(mouseX, mouseY);
	}

	private Optional<InputArea> findTarget(double mouseX, double mouseY) {
		return inputAreas.stream()
			.filter(inputArea -> inputArea.area().isMouseOver(mouseX, mouseY))
			.findFirst();
	}

	public boolean isTarget(IMouseOverable area, double mouseX, double mouseY) {
		return getTarget(mouseX, mouseY)
			.map(inputArea -> inputArea.area() == area)
			.orElse(false);
	}

	Stream<IRecipeFocusSource> getFocusSources(double mouseX, double mouseY) {
		return getTarget(mouseX, mouseY).stream()
			.map(InputArea::area)
			.filter(IRecipeFocusSource.class::isInstance)
			.map(IRecipeFocusSource.class::cast);
	}

	public List<IGuiInputLayer> getForegroundLayers() {
		return inputAreas.stream()
			.map(InputArea::area)
			.filter(IGuiInputLayer.class::isInstance)
			.map(IGuiInputLayer.class::cast)
			.toList();
	}

	Optional<IInputInteraction> startDrag(Screen screen, UserInput input) {
		InputArea target = getTarget(input.getMouseX(), input.getMouseY()).orElse(null);
		if (target != null) {
			for (DragSource source : target.dragSources()) {
				Optional<IInputInteraction> drag = source.begin(screen, input);
				if (drag.isPresent()) {
					return drag;
				}
			}
		}
		return Optional.empty();
	}

	/** Public recipe drag callbacks use the current pointer position, including when no control accepted the press. */
	boolean dragApiHandlers(double mouseX, double mouseY, InputConstants.Key button, double dragX, double dragY) {
		return dispatch(mouseX, mouseY, () -> {
			InputArea target = getTarget(mouseX, mouseY).orElse(null);
			if (target == null) {
				return false;
			}
			return (target.apiDragHandler() != null && target.apiDragHandler().handleMouseDragged(mouseX, mouseY, button, dragX, dragY)) ||
				target.blocksUnhandledMouseInput();
		});
	}

	void resetInput() {
		inputAreas.forEach(inputArea -> inputArea.controls().resetInput());
	}

	/**
	 * The input area selected for one event.
	 *
	 * @param inputArea the selected input area, or null if the pointer is outside every input area
	 */
	private record HitTest(@Nullable InputArea inputArea) {
	}
}

package mezz.jei.gui.input;

import mezz.jei.api.runtime.IJeiKeyMapping;
import mezz.jei.common.config.DebugConfig;
import mezz.jei.common.input.UserInput;
import mezz.jei.common.input.interaction.IInputInteraction;
import mezz.jei.common.input.interaction.InputAction;
import net.minecraft.client.gui.screens.Screen;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.function.BiFunction;
import java.util.function.BooleanSupplier;
import java.util.function.Predicate;

/**
 * Shortcuts tried in the order they were added. The first matching shortcut that can
 * handle the input wins. The same rules apply to keyboard and mouse bindings.
 * {@link GuiInputController} decides which collection of shortcuts to try first.
 *
 * <p>For example, if a player binds two shortcuts in this collection to the same key,
 * the one added first gets the first chance to handle it. The second can run only if
 * the first cannot handle that input, such as when it needs an ingredient under the
 * mouse and there is none.</p>
 */
public final class InputCommands {
	private static final Logger LOGGER = LogManager.getLogger();

	/** Whether a shortcut requires the mouse pointer to be over its input area, for either keyboard or mouse bindings. */
	public enum Scope {
		/**
		 * Works anywhere on a screen where this collection's shortcuts are available.
		 * For example, a player can use the Next Recipe Page shortcut with the mouse pointer
		 * outside the recipe display.
		 */
		SCREEN,
		/**
		 * Works only when this shortcut's input area is the frontmost one under the mouse pointer.
		 * For example, the player must move the mouse over the ingredient list to use its
		 * Quick Move shortcut on an ingredient there.
		 */
		HOVERED
	}

	/** Shortcuts in the order they are tried. */
	private final List<Command> commands = new ArrayList<>();
	/** Screens where any of this collection's shortcuts may run. */
	private final Predicate<Screen> available;

	public InputCommands() {
		this(screen -> true);
	}

	public InputCommands(Predicate<Screen> available) {
		this.available = available;
	}

	public void add(String name, Predicate<UserInput> matches, BiFunction<Screen, UserInput, Optional<IInputInteraction>> prepare) {
		add(Scope.SCREEN, name, matches, prepare);
	}

	public void add(Scope scope, String name, Predicate<UserInput> matches, BiFunction<Screen, UserInput, Optional<IInputInteraction>> prepare) {
		commands.add(new Command(scope, name, matches, prepare));
	}

	public void add(String name, IJeiKeyMapping key, BooleanSupplier enabled, Runnable action) {
		add(name, input -> input.is(key) && enabled.getAsBoolean(),
			(screen, input) -> Optional.of(InputAction.run(action).when(enabled)));
	}

	public Optional<IInputInteraction> resolve(Screen screen, UserInput input, boolean hovered) {
		if (!available.test(screen)) {
			return Optional.empty();
		}
		for (Command command : commands) {
			if ((hovered || command.scope() == Scope.SCREEN) && command.matches().test(input)) {
				Optional<IInputInteraction> action = command.prepare().apply(screen, input);
				if (action.isPresent()) {
					if (DebugConfig.isDebugInputsEnabled()) {
						LOGGER.debug("JEI command {} ({})", command.name(), command.scope());
					}
					return action;
				}
			}
		}
		return Optional.empty();
	}

	/**
	 * A shortcut that selects its action when its key or mouse button is pressed.
	 *
	 * @param scope whether this shortcut's input area must be under the mouse pointer
	 * @param name shortcut name used in debug logs
	 * @param matches checks the binding and any conditions needed to recognize the press
	 * @param prepare creates an interaction and remembers any needed data, such as the ingredient
	 *                under the pointer; returning empty lets the next shortcut try
	 */
	private record Command(Scope scope, String name, Predicate<UserInput> matches, BiFunction<Screen, UserInput, Optional<IInputInteraction>> prepare) {
	}
}

package mezz.jei.common.input.interaction;

import mezz.jei.common.input.IMouseOverable;
import mezz.jei.common.input.UserInput;

import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Predicate;

/**
 * An interaction that runs an action chosen when a key or mouse button is pressed.
 * Before running, it checks whether the action is still allowed.
 *
 * <p>For example, a player clicks cobblestone to view its recipes. The action remembers
 * cobblestone when the player presses the mouse button and shows its recipes when
 * the player lets go, provided the click is still allowed.</p>
 *
 * @param action the action to run, receiving the release event for a mouse click
 *               or the original press event for a keyboard shortcut
 * @param canExecute checks whether the action is still allowed to run; returning false
 *                   skips the action
 */
public record InputAction(Consumer<UserInput> action, Predicate<UserInput> canExecute) implements IInputInteraction {
	public InputAction(Consumer<UserInput> action) {
		this(action, input -> true);
	}

	public static InputAction run(Runnable action) {
		return new InputAction(input -> action.run());
	}

	/** Requires mouse releases to remain over the area. Keyboard shortcuts use the target selected on press. */
	public InputAction within(IMouseOverable area) {
		return new InputAction(action, input -> canExecute.test(input) &&
			(input.isKeyboardInput() || area.isMouseOver(input.getMouseX(), input.getMouseY())));
	}

	/** Checks a condition before running, such as whether a button is still visible or enabled. */
	public InputAction when(BooleanSupplier available) {
		return new InputAction(action, input -> canExecute.test(input) && available.getAsBoolean());
	}

	@Override
	public void complete(UserInput input) {
		if (canExecute.test(input)) {
			action.accept(input);
		}
	}
}

package mezz.jei.common.input.interaction;

import com.mojang.blaze3d.platform.InputConstants;
import mezz.jei.common.input.UserInput;
import org.jspecify.annotations.Nullable;

import java.util.function.Consumer;

/**
 * Calls handlers for mouse movement, release, and cancellation during a drag.
 */
public final class MouseDrag implements IInputInteraction {
	/** Receives mouse movement, or null when the drag needs no movement callback. */
	private final @Nullable IMovement onDrag;
	/** Finishes the drag when the button is released, using the release position if needed. */
	private final Consumer<UserInput> onRelease;
	/** Cleans up the drag when its screen closes or the interaction is replaced. */
	private final Runnable onCancel;
	/** Keeps dragging if JEI receives a duplicate button-press event before release. */
	private final boolean keepOnRepeatedPress;

	private MouseDrag(@Nullable IMovement onDrag, Consumer<UserInput> onRelease, Runnable onCancel, boolean keepOnRepeatedPress) {
		this.onDrag = onDrag;
		this.onRelease = onRelease;
		this.onCancel = onCancel;
		this.keepOnRepeatedPress = keepOnRepeatedPress;
	}

	/**
	 * Handles a scrollbar or resize handle that updates as the mouse moves.
	 * Both release and cancellation stop the drag without undoing those changes.
	 *
	 * <p>For example, a player holds the left mouse button on a scrollbar and drags down.
	 * The list scrolls as they move the mouse, and stays at that position when they let go.</p>
	 *
	 * @param onDrag updates the control as the mouse moves
	 * @param onStop clears the control's drag state on release or cancellation
	 */
	public static MouseDrag forWidget(IMovement onDrag, Runnable onStop) {
		return new MouseDrag(onDrag, ignored -> onStop.run(), onStop, false);
	}

	/**
	 * Handles an ingredient drag that needs only release and cancellation callbacks.
	 * A duplicate button-press event keeps the original drag, as
	 * described in {@link IInputInteraction#keepsCaptureOnRepeatedPress()}.
	 *
	 * <p>For example, a player holds the left mouse button on a bookmark, drags it to
	 * another slot, then lets go to put it there. Closing the inventory before letting
	 * go puts the bookmark back in its original place.</p>
	 *
	 * @param onRelease tries to drop the ingredient or move its bookmark to the release position
	 * @param onCancel stops the drag without dropping the ingredient
	 */
	public static MouseDrag forIngredient(Consumer<UserInput> onRelease, Runnable onCancel) {
		return new MouseDrag(null, onRelease, onCancel, true);
	}

	/** Receives the mouse position and distance moved, as described in {@link IInputInteraction#drag}. */
	@FunctionalInterface
	public interface IMovement {
		void move(double mouseX, double mouseY, InputConstants.Key button, double dragX, double dragY);
	}

	@Override
	public void complete(UserInput input) {
		onRelease.accept(input);
	}

	@Override
	public void drag(double mouseX, double mouseY, InputConstants.Key button, double dragX, double dragY) {
		if (onDrag != null) {
			onDrag.move(mouseX, mouseY, button, dragX, dragY);
		}
	}

	@Override
	public boolean capturesMouseMovement() {
		return onDrag != null;
	}

	@Override
	public void cancel() {
		onCancel.run();
	}

	@Override
	public boolean keepsCaptureOnRepeatedPress() {
		return keepOnRepeatedPress;
	}
}

package mezz.jei.neoforge.events;

import mezz.jei.common.util.ErrorUtil;
import net.neoforged.bus.api.Event;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.fml.event.IModBusEvent;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * Holds all the event subscriptions that JEI needs to work at runtime.
 * These will be cleared and re-registered every time a player leaves a world or enters a new one.
 */
public class RuntimeEventSubscriptions {
	private final List<EventSubscription<?>> subscriptions = new ArrayList<>();
	private final List<Runnable> cleanupActions = new ArrayList<>();
	private final IEventBus eventBus;

	public RuntimeEventSubscriptions(IEventBus eventBus) {
		ErrorUtil.checkNotNull(eventBus, "eventBus");
		this.eventBus = eventBus;
	}

	public <T extends Event> void register(Class<T> eventType, Consumer<T> listener) {
		register(EventPriority.NORMAL, eventType, listener);
	}

	public <T extends Event> void register(EventPriority priority, Class<T> eventType, Consumer<T> listener) {
		if (IModBusEvent.class.isAssignableFrom(eventType)) {
			throw new IllegalArgumentException(String.format("%s must be registered on the mod event bus", eventType));
		}

		EventSubscription<T> subscription = EventSubscription.register(eventBus, priority, eventType, listener);
		this.subscriptions.add(subscription);
	}

	public boolean isEmpty() {
		return subscriptions.isEmpty();
	}

	public void onClear(Runnable cleanup) {
		cleanupActions.add(cleanup);
	}

	public void clear() {
		subscriptions.forEach(EventSubscription::unregister);
		subscriptions.clear();
		List<Runnable> pendingCleanup = List.copyOf(cleanupActions);
		cleanupActions.clear();
		pendingCleanup.forEach(Runnable::run);
	}
}

package mezz.jei.common.input.interaction;

import com.mojang.blaze3d.platform.InputConstants;
import mezz.jei.common.input.IInputTarget;
import mezz.jei.common.input.UserInput;

/**
 * Handles an accepted key press, mouse click, or drag.
 * Mouse movement and release stay with this interaction even if the pointer leaves
 * the original control or a key binding changes.
 *
 * <p>For keyboard input, the controller calls {@link #complete} immediately.
 * Mouse input completes on release or is cancelled when the screen changes or
 * another press replaces the interaction.</p>
 *
 * <p>For example, a player holds the left mouse button on a scrollbar and moves the
 * mouse sideways, outside the scrollbar. Moving the mouse up or down still scrolls
 * the list until the player lets go of the button.</p>
 *
 * @see IInputTarget#beginInput
 * @see InputAction
 * @see MouseDrag
 */
public interface IInputInteraction {
	/**
	 * Finishes handling the input. A click action may be skipped if its original control
	 * is no longer available or the mouse button was released with the pointer outside it.
	 *
	 * @param input the mouse button release event, or the original key press event
	 */
	void complete(UserInput input);

	/**
	 * Called when the player moves the mouse while holding the button that began this interaction,
	 * including movement outside the control.
	 *
	 * @param mouseX current horizontal pointer position in GUI coordinates
	 * @param mouseY current vertical pointer position in GUI coordinates
	 * @param button the mouse button whose press began the interaction
	 * @param dragX horizontal movement since the previous drag event
	 * @param dragY vertical movement since the previous drag event
	 */
	default void drag(double mouseX, double mouseY, InputConstants.Key button, double dragX, double dragY) {
	}

	/**
	 * Whether this interaction prevents public recipe handlers from also receiving mouse movement.
	 * Scrollbars and resize handles return true. The default, false, lets recipe handlers
	 * under the pointer handle movement as well.
	 */
	default boolean capturesMouseMovement() {
		return false;
	}

	/**
	 * Clears pressed or dragging state without running the click action or dropping an ingredient.
	 * For example, if a player closes the inventory while dragging a bookmark, the bookmark
	 * goes back to its original place.
	 */
	default void cancel() {
	}

	/**
	 * Whether to keep this interaction when the same mouse button is reported pressed again
	 * before release. The default, false, cancels it and starts a new click.
	 *
	 * <p>For example, a player is dragging a bookmark while holding the left mouse button.
	 * If JEI receives a duplicate press event, returning true keeps that bookmark attached
	 * to the mouse until the player lets go.</p>
	 */
	default boolean keepsCaptureOnRepeatedPress() {
		return false;
	}
}

package mezz.jei.gui.elements;

import mezz.jei.api.gui.buttons.IIconButtonController;
import mezz.jei.common.gui.JeiTooltip;
import mezz.jei.common.input.IInputTarget;
import mezz.jei.common.input.IInternalKeyMappings;
import mezz.jei.common.input.UserInput;
import mezz.jei.common.input.interaction.IInputInteraction;
import mezz.jei.common.util.ImmutableRect2i;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.Screen;

import java.util.Optional;
import java.util.function.Predicate;

public final class IconButton {
	private final InternalIconButton button;
	private final IIconButtonController controller;
	private ImmutableRect2i area;

	public IconButton(IIconButtonController controller) {
		this(controller, ImmutableRect2i.EMPTY);
	}

	public IconButton(IIconButtonController controller, ImmutableRect2i area) {
		this.controller = controller;
		this.button = new InternalIconButton();
		this.area = area;
		this.controller.initState(this.button);
	}

	public void updateBounds(ImmutableRect2i area) {
		this.button.updateBounds(area);
		this.area = area;
	}

	public void setForcePressed(boolean forcePressed) {
		this.button.setForcePressed(forcePressed);
	}

	public ImmutableRect2i getArea() {
		return area;
	}

	public void draw(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float partialTicks) {
		if (this.area.isEmpty()) {
			return;
		}

		this.button.extractRenderState(guiGraphics, mouseX, mouseY, partialTicks);
		this.controller.drawExtras(guiGraphics, area.toMutable(), mouseX, mouseY, partialTicks);
	}

	public boolean isMouseOver(double mouseX, double mouseY) {
		return this.button.visible && this.area.contains(mouseX, mouseY);
	}

	public IInputTarget createInputHandler() {
		return createInputHandler(input -> false);
	}

	/** Accepts a button-specific shortcut in addition to ordinary left clicks. */
	public IInputTarget createInputHandler(Predicate<UserInput> shortcut) {
		return new ButtonInputHandler(button, controller, shortcut);
	}

	public void tick() {
		this.controller.updateState(this.button);
	}

	public void drawTooltips(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY) {
		if (isMouseOver(mouseX, mouseY)) {
			JeiTooltip tooltip = new JeiTooltip();
			controller.getTooltips(tooltip);
			tooltip.draw(guiGraphics, mouseX, mouseY);
		}
	}

	public boolean isVisible() {
		return button.visible;
	}

	public int getX() {
		return area.getX();
	}

	public int getY() {
		return area.getY();
	}

	public int getWidth() {
		return area.getWidth();
	}

	public int getHeight() {
		return area.getHeight();
	}

	private static class ButtonInputHandler implements IInputTarget {
		private final InternalIconButton button;
		private final IIconButtonController controller;
		private final Predicate<UserInput> shortcut;

		public ButtonInputHandler(InternalIconButton button, IIconButtonController controller, Predicate<UserInput> shortcut) {
			this.button = button;
			this.controller = controller;
			this.shortcut = shortcut;
		}

		@Override
		public Optional<IInputInteraction> beginInput(Screen screen, UserInput input, IInternalKeyMappings keys) {
			boolean hit = button.isActive() && button.isMouseOver(input.getMouseX(), input.getMouseY()) &&
				(input.ifMouseEvent((event, ignoredDoubleClick) -> button.isValidClickButton(event.buttonInfo())) || shortcut.test(input));
			if (!hit) {
				return Optional.empty();
			}
			button.setPressed(true);
			if (input.isSimulate()) {
				controller.onPress(input);
			}
			return Optional.of(new ButtonPress(button, controller));
		}

		@Override
		public void resetInput() {
			this.button.setPressed(false);
		}
	}

	/**
	 * Keeps the button looking pressed until release or cancellation, and runs its action
	 * only if the mouse button is released over it while the control is still enabled.
	 *
	 * @param button the button to check and update on release
	 * @param controller the button's public API handler, called on release to run the action
	 */
	private record ButtonPress(InternalIconButton button, IIconButtonController controller) implements IInputInteraction {
		@Override
		public void complete(UserInput input) {
			button.setPressed(false);
			if (!button.isActive() || !button.isMouseOver(input.getMouseX(), input.getMouseY())) {
				return;
			}
			button.playDownSound(Minecraft.getInstance().getSoundManager());
			if (controller.onPress(input)) {
				controller.updateState(button);
			}
		}

		@Override
		public void cancel() {
			button.setPressed(false);
		}
	}

}

package mezz.jei.gui.elements;

import mezz.jei.common.util.ImmutableSize2i;

/** Uses the initial grab position so clicking inside a border does not make the panel jump. */
public record ResizeDrag(ResizeHandle handle, double mouseX, double mouseY, ImmutableSize2i size) {
	public ImmutableSize2i resize(double x, double y, boolean centeredX, boolean centeredY, ImmutableSize2i minimum, ImmutableSize2i maximum) {
		int width = size.width();
		int height = size.height();
		if (handle.horizontal()) {
			double delta = delta(x - mouseX, handle.left(), centeredX);
			width = (int) Math.round(width + delta);
			width = Math.clamp(width, Math.min(minimum.width(), maximum.width()), maximum.width());
		}
		if (handle.vertical()) {
			double delta = delta(y - mouseY, handle.top(), centeredY);
			height = (int) Math.round(height + delta);
			height = Math.clamp(height, Math.min(minimum.height(), maximum.height()), maximum.height());
		}
		return new ImmutableSize2i(width, height);
	}

	private static double delta(double delta, boolean reversed, boolean centered) {
		if (reversed) {
			delta = -delta;
		}
		if (centered) {
			delta *= 2;
		}
		return delta;
	}
}

package mezz.jei.gui.recipes;

import mezz.jei.common.util.ImmutableRect2i;
import mezz.jei.common.util.ImmutableSize2i;

public record RecipeGuiGrid(int rows, int columns) {
	private static final int MIN_RECIPE_PADDING = 4;

	public static RecipeGuiGrid calculate(ImmutableSize2i availableSize, ImmutableSize2i recipeSizeWithButtons, int maxColumns) {
		int rows = Math.max(1, (availableSize.height() + MIN_RECIPE_PADDING) / (recipeSizeWithButtons.height() + MIN_RECIPE_PADDING));
		int columns = Math.clamp((availableSize.width() + MIN_RECIPE_PADDING) / (recipeSizeWithButtons.width() + MIN_RECIPE_PADDING), 1, maxColumns);
		return new RecipeGuiGrid(rows, columns);
	}

	public int recipesPerPage() {
		return rows * columns;
	}

	public ImmutableRect2i getRecipeArea(int index, ImmutableRect2i availableArea, ImmutableSize2i recipeSize, int recipeWidthWithButtons) {
		int columnWidth = (availableArea.width() - (columns - 1) * MIN_RECIPE_PADDING) / columns;
		int column = index % columns;
		int row = index / columns;
		int columnX = availableArea.x() + column * (columnWidth + MIN_RECIPE_PADDING);
		int buttonSpace = recipeWidthWithButtons - recipeSize.width();
		int recipeX;
		if (columnWidth > recipeSize.width() + 2 * buttonSpace) {
			// Center the recipe itself when its buttons fit off to the side.
			recipeX = columnX + (columnWidth - recipeSize.width()) / 2;
		} else {
			recipeX = columnX + (columnWidth - recipeWidthWithButtons) / 2;
		}

		int availableHeight = Math.max(availableArea.height(), recipeSize.height());
		int recipeSpacing = (availableHeight - rows * recipeSize.height()) / (rows + 1);
		int recipeY = availableArea.y() + recipeSpacing + row * (recipeSize.height() + recipeSpacing);
		return new ImmutableRect2i(recipeX, recipeY, recipeWidthWithButtons, recipeSize.height());
	}
}

package mezz.jei.neoforge.events;

import mezz.jei.common.util.WeakConsumer;
import net.neoforged.bus.api.Event;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.bus.api.IEventBus;

import java.util.function.Consumer;

public class EventSubscription<T extends Event> {
	public static <T extends Event> EventSubscription<T> register(IEventBus eventBus, Class<T> eventType, Consumer<T> listener) {
		return register(eventBus, EventPriority.NORMAL, eventType, listener);
	}

	public static <T extends Event> EventSubscription<T> register(IEventBus eventBus, EventPriority priority, Class<T> eventType, Consumer<T> listener) {
		return new EventSubscription<>(eventBus, priority, eventType, listener);
	}

	private final IEventBus eventBus;
	/**
	 * Keep a strong reference to the listener so that
	 * it is not Garbage Collected until we stop using this subscription.
	 */
	@SuppressWarnings({"FieldCanBeLocal", "unused"})
	private final Consumer<T> listener;
	/**
	 * Workaround for <a href="https://github.com/MinecraftForge/EventBus/issues/39">...</a>
	 * "Listeners are not cleaned up immediately when calling EventBus#unregister"
	 *
	 * We create a weak reference here so that the listeners retained by the Forge EventBus do not cause a memory leak.
	 */
	private final WeakConsumer<T> registeredListener;

	private EventSubscription(IEventBus eventBus, EventPriority priority, Class<T> eventType, Consumer<T> listener) {
		this.eventBus = eventBus;
		this.listener = listener;

		WeakConsumer<T> weakListener = new WeakConsumer<>(listener);
		eventBus.addListener(priority, false, eventType, weakListener);
		this.registeredListener = weakListener;
	}

	public void unregister() {
		this.eventBus.unregister(this.registeredListener);
	}
}

package mezz.jei.gui.util;

import mezz.jei.api.ingredients.IIngredientTypeWithSubtypes;
import mezz.jei.api.ingredients.ITypedIngredient;
import mezz.jei.api.recipe.IFocus;
import mezz.jei.api.recipe.IFocusFactory;
import mezz.jei.api.recipe.RecipeIngredientRole;
import mezz.jei.api.runtime.IIngredientManager;
import mezz.jei.common.config.IClientConfig;
import mezz.jei.common.platform.IPlatformFluidHelperInternal;
import mezz.jei.common.platform.Services;
import net.minecraft.world.level.material.Fluid;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class FocusUtil {
	private final IFocusFactory focusFactory;
	private final IClientConfig clientConfig;
	private final IIngredientManager ingredientManager;

	public FocusUtil(IFocusFactory focusFactory, IClientConfig clientConfig, IIngredientManager ingredientManager) {
		this.focusFactory = focusFactory;
		this.clientConfig = clientConfig;
		this.ingredientManager = ingredientManager;
	}

	public List<IFocus<?>> createFocuses(ITypedIngredient<?> ingredient, List<RecipeIngredientRole> roles) {
		List<ITypedIngredient<?>> ingredients = new ArrayList<>();
		ingredients.add(ingredient);

		if (clientConfig.lookupFluidContentsEnabled().get()) {
			IPlatformFluidHelperInternal<?> fluidHelper = Services.PLATFORM.getFluidHelper();
			getContainedFluid(fluidHelper, ingredient)
				.ifPresent(ingredients::add);
		}

		return roles.stream()
			.<IFocus<?>>flatMap(role -> {
				return ingredients.stream()
					.map(i -> focusFactory.createFocus(role, i));
			})
			.toList();
	}

	private <T> Optional<ITypedIngredient<T>> getContainedFluid(IPlatformFluidHelperInternal<T> fluidHelper, ITypedIngredient<?> ingredient) {
		return fluidHelper.getContainedFluid(ingredient)
			.flatMap(fluid -> {
				IIngredientTypeWithSubtypes<Fluid, T> type = fluidHelper.getFluidIngredientType();
				return ingredientManager.createTypedIngredient(type, fluid, false);
			});
	}
}

package mezz.jei.gui.input;

import mezz.jei.common.input.IInternalKeyMappings;
import mezz.jei.common.input.UserInput;
import net.minecraft.client.Minecraft;

import java.util.stream.Stream;

/** Finds ingredients under the mouse pointer in the selected input area for recipe lookup and other shortcuts. */
public class IngredientFocusSource {
	private final GuiInputScene inputScene;

	public IngredientFocusSource(GuiInputScene inputScene) {
		this.inputScene = inputScene;
	}

	public Stream<IClickableIngredientInternal<?>> getIngredientUnderMouse(UserInput input, IInternalKeyMappings keyBindings) {
		double mouseX = input.getMouseX();
		double mouseY = input.getMouseY();

		Stream<IClickableIngredientInternal<?>> stream = getIngredientUnderMouse(mouseX, mouseY);

		if (isConflictingVanillaMouseButton(input, keyBindings)) {
			stream = stream.filter(IClickableIngredientInternal::canClickToFocus);
		}

		return stream;
	}

	Stream<IClickableIngredientInternal<?>> getIngredientUnderMouse(double mouseX, double mouseY) {
		return inputScene.getFocusSources(mouseX, mouseY)
			.flatMap(source -> source.getIngredientUnderMouse(mouseX, mouseY));
	}

	/**
	 * Checks whether the input uses a binding Minecraft normally uses to interact with items.
	 * For example, left-clicking an inventory slot should pick up its stack, so JEI only
	 * uses that click for recipe lookup when the ingredient allows it.
	 *
	 * @see IClickableIngredientInternal#canClickToFocus()
	 */
	private static boolean isConflictingVanillaMouseButton(UserInput input, IInternalKeyMappings keyBindings) {
		Minecraft minecraft = Minecraft.getInstance();
		return input.is(keyBindings.getLeftClick()) ||
			input.is(minecraft.options.keyPickItem) ||
			input.is(keyBindings.getRightClick());
	}
}

